103	/**
104	 * @brief 运行时画一枚 36x36 的蓝色准星（ARGB8888）。
105	 *
106	 * 板端两枚箭头都是编译进 flash 的位图；模拟器要验证"可换图"，再带一张
107	 * 完全不同的图最直观，也避免依赖 PNG 解码器。
108	 */
109	static void alt_icon_build(void)
110	{
111	    enum { W = 36, H = 36 };
112	
113	    s.alt_px = (uint8_t *)lv_malloc((size_t)W * H * 4u);
114	    if (s.alt_px == NULL) {
115	        return;
116	    }
117	    memset(s.alt_px, 0, (size_t)W * H * 4u);
118	
119	    for (int y = 0; y < H; y++) {
120	        for (int x = 0; x < W; x++) {
121	            const double dx = (double)x - (W - 1) / 2.0;
122	            const double dy = (double)y - (H - 1) / 2.0;
123	            const double r = sqrt(dx * dx + dy * dy);
124	            uint32_t argb = 0u;
125	
126	            if (r >= 14.5 && r <= 16.5) {
127	                argb = 0xFF1D6FD0u;                  /* 外圈：蓝 */
128	            } else if (r >= 12.0 && r <= 13.0) {
129	                argb = 0xFFFFFFFFu;                  /* 内圈：白 */
130	            } else if (r <= 3.2) {
131	                argb = 0xFF1D6FD0u;                  /* 中心点 */
132	            } else if ((fabs(dx) <= 1.0 && fabs(dy) >= 9.0 && fabs(dy) <= 16.5)
133	                || (fabs(dy) <= 1.0 && fabs(dx) >= 9.0 && fabs(dx) <= 16.5)) {
134	                argb = 0xFF1D6FD0u;                  /* 四个方向的刻度 */
135	            }
136	
137	            if (argb != 0u) {
138	                uint8_t * p = s.alt_px + ((size_t)y * W + (size_t)x) * 4u;
139	
140	                p[0] = (uint8_t)(argb & 0xFFu);        /* B */
141	                p[1] = (uint8_t)((argb >> 8) & 0xFFu); /* G */
142	                p[2] = (uint8_t)((argb >> 16) & 0xFFu);/* R */
143	                p[3] = (uint8_t)((argb >> 24) & 0xFFu);/* A */
144	            }
145	        }
146	    }
147	
148	    memset(&s.alt_dsc, 0, sizeof(s.alt_dsc));
149	    s.alt_dsc.header.magic = LV_IMAGE_HEADER_MAGIC;
150	    s.alt_dsc.header.cf = LV_COLOR_FORMAT_ARGB8888;
151	    s.alt_dsc.header.w = W;
152	    s.alt_dsc.header.h = H;
153	    s.alt_dsc.header.stride = W * 4;
154	    s.alt_dsc.data_size = W * H * 4u;
155	    s.alt_dsc.data = s.alt_px;
156	}
