315	/**
316	 * @brief 脚本化平移：首帧渲染完成后执行一次，并打印同一地物的像素位移。
317	 */
318	static void pan_script_run(void)
319	{
320	    int32_t x0 = 0;
321	    int32_t y0 = 0;
322	    int32_t x1 = 0;
323	    int32_t y1 = 0;
324	    double lon2 = 0.0;
325	    double lat2 = 0.0;
326	
327	    s.pan_pending = false;
328	    s.pan_applied = true;
329	
330	    /* 参考地物 = 初始中心点。拖动前后各投一次屏幕坐标。 */
331	    (void)vmap_view_geo_to_viewport_raw(s.view, s.lon, s.lat, &x0, &y0);
332	
333	    vmap_view_pan_begin(s.view);
334	    s.follow = false;
335	    vmap_view_pan_px(s.view, s.pan_dx, s.pan_dy);
336	    vmap_view_pan_end(s.view);
337	    s.drag_px += s.pan_dx;
338	    s.drag_py += s.pan_dy;
339	
340	    (void)vmap_view_geo_to_viewport_raw(s.view, s.lon, s.lat, &x1, &y1);
341	    vmap_view_update_arrow(s.view, s.lon, s.lat, 0.0f);
342	    vmap_view_get_center(s.view, &lon2, &lat2);
343	
344	    printf("[vmap-pan] requested=(%+d,%+d) ref=(%.6f,%.6f) before=(%d,%d) "
345	           "after=(%d,%d) delta=(%+d,%+d) new_center=(%.6f,%.6f) follow=%d\n",
346	        s.pan_dx, s.pan_dy, s.lon, s.lat, (int)x0, (int)y0, (int)x1, (int)y1,
347	        (int)(x1 - x0), (int)(y1 - y0), lon2, lat2,
348	        (int)vmap_view_is_following(s.view));
349	}
350	
351	static void drag_cb(lv_event_t * e)
352	{
353	    const lv_event_code_t code = lv_event_get_code(e);
354	    lv_indev_t * indev;
355	
356	    if (s.view == NULL) {
357	        return;
358	    }
359	
360	    switch (code) {
361	        case LV_EVENT_PRESSED:
362	            vmap_view_pan_begin(s.view);
363	            s.follow = false;
364	            break;
365	        case LV_EVENT_PRESSING: {
366	            lv_point_t v;
367	
368	            indev = lv_indev_active();
369	            if (indev == NULL) {
370	                break;
371	            }
372	            lv_indev_get_vect(indev, &v);
373	            if (v.x != 0 || v.y != 0) {
374	                vmap_view_pan_px(s.view, v.x, v.y);
375	                s.drag_px += v.x;
376	                s.drag_py += v.y;
377	                /* follow 已打断：图标按经纬度跟着地面走。 */
378	                vmap_view_update_arrow(s.view, s.lon, s.lat, 0.0f);
379	            }
380	            break;
381	        }
382	        case LV_EVENT_RELEASED:
383	        case LV_EVENT_PRESS_LOST:
384	            vmap_view_pan_end(s.view);
385	            vmap_view_update_arrow(s.view, s.lon, s.lat, 0.0f);
386	            break;
387	        default:
388	            break;
389	    }
390	}
