402	static void center_cycle(void)
403	{
404	    static int idx;
405	    const int n = (int)(sizeof(k_centers) / sizeof(k_centers[0]));
406	
407	    idx = (idx + 1) % n;
408	    s.lon = k_centers[idx].lon;
409	    s.lat = k_centers[idx].lat;
410	    s.drag_px = 0;
411	    s.drag_py = 0;
412	    s.follow = true;
413	
414	    /* 直接定位：运行时换中心点，清偏移并重画。 */
415	    vmap_view_center_on(s.view, s.lon, s.lat);
416	    vmap_view_set_follow_mode(s.view, true);
417	    vmap_view_update_arrow(s.view, s.lon, s.lat, 0.0f);
418	    printf("[vmap] center -> %s (%.6f,%.6f)\n", k_centers[idx].name, s.lon, s.lat);
419	}
