421	static void key_handle(int key)
422	{
423	    switch (key) {
424	        case '1': s.icon = SIM_VMAP_ICON_DEV;  icon_apply(); break;
425	        case '2': s.icon = SIM_VMAP_ICON_ALT;  icon_apply(); break;
426	        case '3': s.icon = SIM_VMAP_ICON_NONE; icon_apply(); break;
427	        case 'i': s.icon = (s.icon + 1) % 3;   icon_apply(); break;
428	        case 'c': center_cycle(); break;
429	        case '+': set_scale_deferred(s.scale * LIVE_WHEEL_STEP); break;
430	        case '-': set_scale_deferred(s.scale / LIVE_WHEEL_STEP); break;
431	        case 'f':
432	            if (s.follow) {
433	                vmap_view_pan_begin(s.view);
434	                s.follow = false;
435	                vmap_view_update_arrow(s.view, s.lon, s.lat, 0.0f);
436	            } else {
437	                vmap_view_set_follow_mode(s.view, true);
438	                s.follow = true;
439	                s.drag_px = 0;
440	                s.drag_py = 0;
441	                vmap_view_update_arrow(s.view, s.lon, s.lat, 0.0f);
442	            }
443	            printf("[vmap] follow=%d\n", (int)s.follow);
444	            break;
445	        case 'r': reset_view(); break;
446	        default: break;
447	    }
448	}
