450	/* ─────────────────────────────────────────────────────────────────────────
451	 * 每拍工作（沿用页面的 10 ms pump 节奏，不引入新的高频定时器）
452	 * ──────────────────────────────────────────────────────────────────────── */
453	
454	static void live_tick(lv_timer_t * t)
455	{
456	    (void)t;
457	
458	    if (s.view == NULL) {
459	        return;
460	    }
461	
462	    /* 运行时改视口：等首帧完成后调组件 API（不是重建视图）。 */
463	    if (s.resize_pending && !vmap_view_render_busy(s.view)
464	        && vmap_view_render_revision(s.view) > 0u) {
465	        s.resize_pending = false;
466	        s.resize_applied = true;
467	        viewport_resize(s.resize_w, s.resize_h);
468	    }
469	
470	    /* 脚本化平移：等首帧（render_revision > 0）完成后做一次。 */
471	    if (s.pan_pending && !vmap_view_render_busy(s.view)
472	        && vmap_view_render_revision(s.view) > 0u) {
473	        pan_script_run();
474	    }
475	
476	    {
477	        const int wheel = sim_display_take_wheel();
478	
479	        if (wheel != 0) {
480	            set_scale_deferred(s.scale * pow(LIVE_WHEEL_STEP, (double)wheel));
481	        }
482	    }
483	
484	    for (int k = sim_display_take_raw_key(); k != 0; k = sim_display_take_raw_key()) {
485	        key_handle(k);
486	    }
487	
488	    if (vmap_view_render_busy(s.view)) {
489	        vmap_view_render_pump(s.view, 8);
490	    } else if (s.pending_scale > 0.0) {
491	        const double sc = s.pending_scale;
492	
493	        s.pending_scale = 0.0;
494	        s.scale = sc;
495	        vmap_view_set_scale(s.view, sc);
496	        vmap_view_render(s.view);
497	    }
498	
499	    s.follow = vmap_view_is_following(s.view);
500	    hud_update();
501	}
