588	    lv_obj_remove_flag(s.holder, LV_OBJ_FLAG_SCROLLABLE);
589	    lv_obj_remove_flag(s.holder, LV_OBJ_FLAG_OVERFLOW_VISIBLE);
590	
591	    /* 红框 = 视口边界（只用于肉眼核对裁切/居中，不是地图的一部分）。 */
592	    {
593	        lv_obj_t * frame = lv_obj_create(scr);
594	
595	        s.frame = frame;
596	        lv_obj_remove_style_all(frame);
597	        lv_obj_set_size(frame, s.vw + 2, s.vh + 2);
