        lon0, lat0, (int)bx, (int)by, (int)ax, (int)ay,
        (int)(ax - bx), (int)(ay - by), (int)s.follow);
}

/**
 * @brief 连续拖动：每拍推进一步（泵忙就等），最后核对同一地物的像素位移。
 *
 * 请求量是 `N × (dx,dy)`；实测 = 初始中心地物在拖动前后投到视口的坐标差。
 * 亚像素累积正确时两者严格相等（老实现会少 1 px）。
 */
static void drag_script_step(void)
{
    if (!s.drag_started) {
        s.drag_started = true;
        (void)vmap_view_geo_to_viewport_raw(s.view, s.lon, s.lat,
            &s.drag_x0, &s.drag_y0);
        vmap_view_pan_begin(s.view);
        s.follow = false;
        printf("[vmap-drag] N=%d step=(%+d,%+d) start=(%d,%d)\\n",
            s.drag_n, s.drag_step_x, s.drag_step_y, (int)s.drag_x0, (int)s.drag_y0);
    }

    if (s.drag_left > 0) {
        vmap_view_pan_px(s.view, s.drag_step_x, s.drag_step_y);
        s.drag_left--;
        s.drag_dx += s.drag_step_x;
        s.drag_dy += s.drag_step_y;
        return;                 /* 下一拍（泵空闲后）再走下一步 */
    }

    {
        int32_t x1 = 0;
        int32_t y1 = 0;

        vmap_view_pan_end(s.view);
        (void)vmap_view_geo_to_viewport_raw(s.view, s.lon, s.lat, &x1, &y1);
        vmap_view_update_arrow(s.view, s.lon, s.lat, 0.0f);
        vmap_view_get_center(s.view, &s.lon, &s.lat);
        s.drag_done = true;
        printf("[vmap-drag] requested=(%+d,%+d) measured=(%+d,%+d) "
               "err=(%+d,%+d) end=(%d,%d) follow=%d\\n",
            s.drag_dx, s.drag_dy, (int)(x1 - s.drag_x0), (int)(y1 - s.drag_y0),
            (int)((x1 - s.drag_x0) - s.drag_dx),
            (int)((y1 - s.drag_y0) - s.drag_dy),
            (int)x1, (int)y1, (int)vmap_view_is_following(s.view));
    }
}

